const LRUCache = require('./s5_cache.js');

describe('LRUCache', function() {
  describe('#get', function() {
    it('should return undefined for a non-existent key', function() {
      const cache = new LRUCache(2);
      assert.strictEqual(cache.get('key1'), undefined);
    });

    it('should return the value for an existing key', function() {
      const cache = new LRUCache(2);
      cache.set('key1', 'value1');
      assert.strictEqual(cache.get('key1'), 'value1');
    });

    it('should update the recency of a key', function() {
      const cache = new LRUCache(2);
      cache.set('key1', 'value1');
      cache.set('key2', 'value2');
      cache.get('key1');
      cache.set('key3', 'value3');
      assert.strictEqual(cache.get('key1'), 'value1');
      assert.strictEqual(cache.get('key2'), undefined);
    });
  });

  describe('#set', function() {
    it('should add a new key-value pair', function() {
      const cache = new LRUCache(2);
      cache.set('key1', 'value1');
      assert.strictEqual(cache.get('key1'), 'value1');
    });

    it('should update the value of an existing key', function() {
      const cache = new LRUCache(2);
      cache.set('key1', 'value1');
      cache.set('key1', 'value2');
      assert.strictEqual(cache.get('key1'), 'value2');
    });

    it('should evict the least recently used key when at capacity', function() {
      const cache = new LRUCache(2);
      cache.set('key1', 'value1');
      cache.set('key2', 'value2');
      cache.set('key3', 'value3');
      assert.strictEqual(cache.get('key1'), undefined);
      assert.strictEqual(cache.get('key2'), 'value2');
      assert.strictEqual(cache.get('key3'), 'value3');
    });
  });
});

